argv:
set -euo pipefail; LAB=dore-design/knowledge-lab/storybook; mkdir -p "$LAB/.storybook" "$LAB/src"; cd "$LAB"; cat > package.json <<'EOF'
{
  "name": "dore-design-knowledge-lab-storybook",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "storybook": "storybook dev -p 6006",
    "build-storybook": "storybook build"
  },
  "dependencies": {
    "react": "^19.1.1",
    "react-dom": "^19.1.1"
  },
  "devDependencies": {
    "@storybook/addon-essentials": "^9.1.3",
    "@storybook/react-vite": "^9.1.3",
    "storybook": "^9.1.3",
    "vite": "^7.1.3"
  }
}
EOF
cat > .storybook/main.js <<'EOF'
export default {
  stories: ['../src/**/*.stories.@(js|jsx|mjs|ts|tsx)'],
  addons: ['@storybook/addon-essentials'],
  framework: { name: '@storybook/react-vite', options: {} }
};
EOF
cat > .storybook/preview.js <<'EOF'
export default {
  parameters: {
    layout: 'fullscreen',
    controls: { expanded: true }
  }
};
EOF
cat > src/EditorialHero.jsx <<'EOF'
import React from 'react';
export function EditorialHero({ eyebrow='WESTSIDE WATCH', title='Watch for the Dawn', deck='在黑夜仍然守望，在清晨尚未來到以前保存光。' }) {
  return <section style={{minHeight:'72vh',padding:'8vw',display:'grid',alignContent:'end',gap:'1rem',background:'#0b2133',color:'#d6aa33',fontFamily:'Georgia, serif'}}><small style={{letterSpacing:'.22em'}}>{eyebrow}</small><h1 style={{fontSize:'clamp(3rem,9vw,8rem)',lineHeight:.9,margin:0,fontWeight:500}}>{title}</h1><p style={{maxWidth:'42rem',fontSize:'clamp(1rem,2vw,1.4rem)',color:'#f0e9dc'}}>{deck}</p></section>;
}
EOF
cat > src/EditorialHero.stories.jsx <<'EOF'
import React from 'react';
import { EditorialHero } from './EditorialHero.jsx';
export default { title: 'Research/EditorialHero', component: EditorialHero, tags: ['autodocs'] };
export const Dawn = {};
export const LongDeck = { args: { deck: '文章、聖經、教會生活與研究，在同一座城中彼此照亮。' } };
EOF
npm install --no-audit --no-fund; npm run build-storybook; test -f storybook-static/index.html; find src -name '*.stories.*' -print -quit | grep .; git add dore-design/knowledge-lab/storybook 2>/dev/null || git add -A; git add -A; if ! git diff --cached --quiet; then git commit -m 'design: make Doré Storybook lab executable'; git push origin HEAD:main; fi
